// The showcase wish worlds (runtime/wishWorlds.ts, data generated by scripts/bake-wish-worlds.ts): each is a complete, normal level of its base theme wearing a generated look, and its art is registered under its look id.
import { existsSync, readFileSync } from "node:fs";
import { afterEach, describe, expect, it } from "vitest";
import { BACKDROPS, backdropFor, isBackdropRegistered, unregisterBackdrop } from "../src/features/game/world/runtime/backdrop";
import { LEVELS, levelWorld, THEMES } from "../src/features/game/world/runtime/catalog";
import { WISH_DATA } from "../src/features/game/world/runtime/wishWorlds.data";
import { findWish, registerWishArt, registerWishArtForLook, wishCards, wishLevel } from "../src/features/game/world/runtime/wishWorlds";
import { SHOWCASE } from "../scripts/lib/world-showcase";
import { BASES, isLookId, parseLook } from "../shared/worldBrief";

const root = new URL("..", import.meta.url).pathname;
afterEach(() => { for (const w of WISH_DATA) unregisterBackdrop(w.look.id); });

describe("the showcase data", () => {
  it("has every showcase wish, with unique ids and unique look ids", () => {
    expect(WISH_DATA.map((w) => w.id)).toEqual(SHOWCASE.map((j) => j.id));
    expect(new Set(WISH_DATA.map((w) => w.look.id)).size).toBe(WISH_DATA.length);
    for (const w of WISH_DATA) expect(isLookId(w.look.id), w.id).toBe(true);
  });
  it("every stored look is one parseLook would read back as it is (a valid, in-band WorldLook)", () => {
    for (const w of WISH_DATA) expect(parseLook(JSON.parse(JSON.stringify(w.look))), w.id).toEqual(w.look);
  });
  it("an outdoor world has all three art layers marked made and a URL for each; an indoor one has no art and the room base", () => {
    for (const w of WISH_DATA) {
      if (w.look.kind === "outdoor") {
        expect(w.look.art, w.id).toEqual({ farDay: true, farNight: true, mid: true });
        expect(Object.keys(w.art!).sort()).toEqual(["farDay", "farNight", "mid"]);
        for (const u of Object.values(w.art!)) expect(typeof u === "string" && u.length > 0, `${w.id} ${u}`).toBe(true);
        expect(w.base).not.toBe("room");
      } else {
        expect(w.art, w.id).toBeNull();
        expect(w.base).toBe("room");
        expect(w.look.room, w.id).toBeTruthy();
      }
    }
  });
  it("the baked assets exist on disk for every outdoor world, and are real images (RIFF WEBP)", () => {
    for (const w of WISH_DATA.filter((x) => x.look.kind === "outdoor")) {
      for (const piece of ["far-day", "far-night", "mid"]) {
        const f = `${root}src/features/game/world/runtime/assets/looks/${w.id}-${piece}.webp`;
        expect(existsSync(f), f).toBe(true);
        const head = readFileSync(f).subarray(0, 12);
        expect(head.subarray(0, 4).toString("latin1") + head.subarray(8, 12).toString("latin1"), f).toBe("RIFFWEBP");
      }
    }
  });
  it("every base is a real base theme and every name is a short, plain card title", () => {
    for (const w of WISH_DATA) {
      expect((BASES as readonly string[]).includes(w.base), w.id).toBe(true);
      expect(THEMES[w.base] != null || w.base === "room", w.id).toBe(true);
      expect(w.look.name.length).toBeGreaterThanOrEqual(3);
      expect(w.look.name.length).toBeLessThanOrEqual(28);
    }
  });
});

describe("wishLevel", () => {
  it("is a complete level of the base theme, called what the look is called, with the base world's own props and hiding spots", () => {
    for (const w of WISH_DATA) {
      const l = wishLevel(w.id)!;
      const base = LEVELS.find((x) => x.id === w.base)!;
      expect(l.format).toBe("toyventor.level/1");
      expect(l.id).toBe("kid-world");
      expect(l.name).toBe(w.look.name);
      expect(l.theme).toBe(w.base);
      expect(l.props).toEqual(base.props);
      expect(l.spots).toEqual(base.spots);
      expect(l.look).toEqual(w.look);
      expect(l.props.length).toBeGreaterThan(0);
    }
  });
  it("is a fresh copy every time (editing the level in Create must not change the base world or the next wish)", () => {
    const a = wishLevel("candy-forest")!, b = wishLevel("candy-forest")!;
    a.props.push({ type: "tree", x: 99 });
    a.look!.name = "Changed";
    expect(b.props.length).toBe(LEVELS.find((x) => x.id === "garden")!.props.length);
    expect(b.look!.name).toBe(findWish("candy-forest")!.look.name);
    expect(LEVELS.find((x) => x.id === "garden")!.props.some((p) => p.x === 99)).toBe(false);
  });
  it("levelWorld gives it its base theme's physics and the look on the world", () => {
    const w = levelWorld(wishLevel("jellyfish-ocean")!);
    expect(w.theme).toBe("beach");
    expect(w.gen.id).toBe(findWish("jellyfish-ocean")!.look.id);
    expect(w.spots.length).toBe(LEVELS.find((x) => x.id === "beach")!.spots.length);
  });
  it("is null for an unknown wish", () => { expect(wishLevel("nope")).toBeNull(); expect(findWish("__proto__")).toBeNull(); });
});

describe("registering the art", () => {
  it("an outdoor world's art answers for its look id in both looks, a different world's does not, and the base theme's art is what everyone else gets", () => {
    const w = findWish("candy-forest")!;
    expect(isBackdropRegistered(w.look.id)).toBe(false);
    expect(registerWishArt("candy-forest")).toBe(true);
    expect(backdropFor("garden", "day", w.look.id)!.layers[0]!.url).toBe(w.art!.farDay);
    expect(backdropFor("garden", "night", w.look.id)!.layers[0]!.url).toBe(w.art!.farNight);
    expect(backdropFor("garden", "day", w.look.id)!.layers[1]!.url).toBe(w.art!.mid);
    expect(backdropFor("garden", "day", findWish("rainbow-clouds")!.look.id)).toBe(BACKDROPS.garden!.day);
    expect(backdropFor("garden", "day")).toBe(BACKDROPS.garden!.day);
  });
  it("an indoor world registers nothing (no painted layers) but is still a known wish; a stored look finds its showcase art by id", () => {
    expect(registerWishArt("pirate-room")).toBe(true);
    expect(isBackdropRegistered(findWish("pirate-room")!.look.id)).toBe(false);
    expect(registerWishArt("nope")).toBe(false);
    expect(registerWishArtForLook(findWish("ice-cream-peak")!.look.id)).toBe(true);
    expect(isBackdropRegistered(findWish("ice-cream-peak")!.look.id)).toBe(true);
    expect(registerWishArtForLook("gen-0000000000")).toBe(false);
  });
  it("the cards are the worlds' names, in order", () => {
    expect(wishCards()).toEqual(WISH_DATA.map((w) => ({ id: w.id, name: w.look.name })));
  });
});
